VALUES ('2026-W32', 'a7bdd464-f988-500e-8197-3f1c1264a5cf', 'S2 "Framework wobbles; distribution grinds on; leadership stays split" (40%)', 'Partial', '[{"grade":"Partial","id":"S1","note":"The equity legs materialized almost exactly (records above 7,600, breadth >69%, Russell participating, VIX 14-16, HY <275) via the soft-data trigger - but the oil leg inverted (Brent rose toward $88, not under $85), gold went the opposite way (+8% vs \"heavy toward $4,000\") and BTC never reclaimed $66K.","probability":35,"source":"sidecar 2026-W34","targets_hit":null,"targets_n":null,"title":"The framework holds; disinflation re-arms the hold case"},{"grade":"Not","id":"S3","note":"Credit tightened 13 bps instead of taking 300, Iran didn''t repudiate, and NFP missed cold rather than hot.","probability":25,"source":"sidecar 2026-W34","targets_hit":null,"targets_n":null,"title":"The framework collapses, or credit finally confirms"}]'::jsonb, 'wrong - breadth repaired to 72.76%, HY round-tripped to 271 bps and the Russell set records; every cited internals leg inverted, leaving the Stage-3 call standing on the macro layer alone', 'valid - sixth week in the box; the failed $65K breakout on a best-since-April inflow week worsens composition, not the phase', 'The phase call capped the scenario (40% on a chop-ceiling that the hike''s death melted through by ~250 pts), and gold was priced off the war leg alone while the term-premium/debasement bid drove +8%; NAAIM went dark mid-arc. Graded over two weeks (no W33 journal).', NULL, NULL, NULL, false, TIMESTAMPTZ '2026-08-17T00:00:00Z')
