VALUES ('2026-W35', '8d845a76-0f58-5c87-bfe6-6bb6f13f695b', 'S2 "The turf fight stays unresolved; the long end stays elevated; the two books stay decoupled" (40%)', 'Partial', '[{"grade":"Partial","id":"S1","note":"Core PCE printed 0.2%, Warsh kept a hike live, the 2Y cleared 4.35% intraday, and gold entered the target band; tech outperformed and BTC never retested $66K–$70K.","probability":30,"source":"sidecar 2026-W36","targets_hit":null,"targets_n":null,"title":"Warsh reasserts; the long end calms; the de-rate deepens"},{"grade":"Not","id":"S3","note":"Cook was not removed, the 30Y did not break 5.40%, core PCE stayed below 0.3%, and Brent did not reach $100.","probability":30,"source":"sidecar 2026-W36","targets_hit":null,"targets_n":null,"title":"The independence discount blows out, or the oil leg re-arms"}]'::jsonb, 'valid - Phase 3 held, but tighter credit and lower vol rejected contraction', 'valid - Phase 1 held; breakout and positive flows survived, but BTC''s inflow streak broke', 'Coupled Fed credibility to continued tech reward decay. Warsh delivered the hawkish branch, but NVIDIA''s exceptional beat reset the valuation bar while Marvell showed an ordinary beat-and-raise still failed. Also read sanctions escalation as oil direction when reopening hopes drove the weekly move.', NULL, NULL, NULL, false, TIMESTAMPTZ '2026-08-31T00:00:00Z')
